# *****************************************************************************
# User-configurable settings for project_mofa_factors.R.
#
# This file mirrors the relevant parts of MOFA_parameters.R and
# glm_factor_estimate_parameters.R. It identifies the external omics and
# clinical data, specifies timepoint/change-score preprocessing, identifies the
# saved MOFA feature weights, and configures projectMofaFactors().
# *****************************************************************************

# Full path to feature_weights.rds generated by a previous run of
# MOFA_analysis.R. This file contains a named list of view-specific MOFA feature
# weight matrices and is required for factor projection.
feature_weights_fn <- file.path("D:/R_sessions/PROSPR/MOFA/foo",
		"2026_Sep_23_18_16_57_visit=24mo_change_scores_views=pr+mb",
		"feature_weights.rds")

# Optional path to mofa_glm_predictor.rds generated by mofa_train_glm.R.
# This object supplies view/factor-specific internal-CV quality metrics used by
# combine_views = "best_cv" or "weighted_cv". Leave NULL when using "mean",
# "median", or "none" and no CV-aware combination is desired.
glm_predictor_fn <- file.path("D:/R_sessions/PROSPR/MOFA/foo",
		"2026_Sep_23_18_16_57_visit=24mo_change_scores_views=pr+mb/glm_model",
		"mofa_glm_predictor.rds")

# Optional output root. If NULL, results are written beneath the folder that
# contains feature_weights_fn.
output_dir <- NULL

# Study name used in generated documentation and spreadsheet sheet names.
study_name <- "CALERIE"

# Names of the subject identifier, treatment, and timepoint columns in the
# clinical data file.
subject_id_col <- "DEID"
treatment_col <- "CR"
timepoint_col <- "fumo"

# Map user-facing timepoint labels to codes in the clinical data. Exactly one
# entry must be named "baseline".
timepoint_labels <- setNames(
  c(0, 12, 24, 3, 6, 18, 98, 99),
  c("baseline", "12mo", "24mo", "3mo", "6mo", "18mo", "BLs1", "BLs2")
)

# Map user-facing treatment labels to codes in the clinical data.
treatment_labels <- setNames(c(0, 1), c("AL", "CR"))

# Target visit whose samples will be projected.
timepoint <- 24

# If TRUE, compute target-minus-baseline change scores. If FALSE, use target
# visit values directly.
use_change_scores <- TRUE

# If TRUE, z-score each retained feature across the selected external samples
# before projection. Set this consistently with the preprocessing scale of the
# data used to train the MOFA model that produced feature_weights.rds.
scale_views <- TRUE

# -----------------------------------------------------------------------------
# Input file locations. Comment out a view-specific file variable to exclude it.
# -----------------------------------------------------------------------------

# methy_fn <- file.path("E:/Data/PROSPR-FAST/CALERIE/methylation",
#   "CALERIE_GRSet_CPR_processing_reliable_subset_mvals.rds")

 prot_fn <- file.path("E:/Data/PROSPR-FAST/CALERIE/proteomics",
   "CALERIE_somascan_processed_unique_human_proteins_matrix.csv")

 metab_data_fn <- file.path("E:/Data/PROSPR-FAST/CALERIE/metabolomics",
   "CALERIE_metabolon.csv")
 metab_annot_fn <- file.path("E:/Data/PROSPR-FAST/CALERIE/metabolomics",
   "metabolon_annotations.csv")

# Clinical/phenotype data are required.
clin_fn <- file.path("E:/Data/PROSPR-FAST/CALERIE/clinical",
  "CALERIE_clinical_w_omics_crosswalks.csv")

resource_vars <- c(
  "methy_fn", "prot_fn", "metab_data_fn", "metab_annot_fn", "clin_fn"
)

# Definitions for optional external omics views. View names must match the names
# stored in feature_weights.rds for the corresponding view to be projected.
omics_input_defs <- list(
  methylation = list(
    moniker = "me",
    file_var = "methy_fn",
    barcode_col = "blood_DNAm_barcode",
    reader = function(fn) readMethylation(fn),
    readme_notes = list(
      change_scores = "Methylation data are reported as M-values.",
      timepoint_values = "Methylation data are reported as M-values."
    )
  ),
  proteomics = list(
    moniker = "pr",
    file_var = "prot_fn",
    barcode_col = "proteomics_barcode",
    reader = function(fn) readProteomics(fn),
    readme_notes = list(
      change_scores = paste("Proteomics data, from Somascan, are already", "log2 transformed."),
      timepoint_values = paste("Proteomics data, from Somascan, are already", "log2 transformed.")
    )
  ),
  metabolomics = list(
    moniker = "mb",
    file_var = "metab_data_fn",
    barcode_col = "metabolomics_barcode",
    reader = function(fn) readMetabolomics(fn)[["data"]],
    readme_notes = list(
      change_scores = paste(
        "Metabolomics data in", study_name,
        "are reported in Metabolon median-centered units; accordingly,",
        "we log2 transform them prior to change-score calculation."
      ),
      timepoint_values = paste(
        "Metabolomics data in", study_name,
        "are reported in Metabolon median-centered units; accordingly,",
        "we log2 transform them prior to analysis."
      )
    )
  )
)

# -----------------------------------------------------------------------------
# projectMofaFactors() settings.
# -----------------------------------------------------------------------------

# How to combine view-specific projections of the same factor.
# Choices: "mean", "median", "best_cv", "weighted_cv", "none".
# "best_cv" and "weighted_cv" require glm_predictor_fn to identify a valid
# MofaFactorPredictor object generated by mofa_train_glm.R.
combine_views <- "weighted_cv"

# Internal-CV metric used when combine_views is "best_cv" or "weighted_cv".
# Supported values: "pearson", "spearman", "r_squared", "rmse", "mae".
metric <- "pearson"

# Ridge regularization strength in the projection
#   X' W (W' W + ridge_lambda * I)^(-1)
# Positive values stabilize the projection and shrink extreme factor estimates.
ridge_lambda <- 1

# Print progress messages about ignored views, dropped samples, and CV-aware
# view selection.
verbose <- TRUE
